  const feedbackForm=()=>`<form class="app-form feedback-form" id="feedback-form" novalidate><label>Mikä toimi, mikä ei, mitä puuttuu?<textarea name="msg" rows="4" maxlength="2000" placeholder="Esim. kuitin lisäys oli hankala, koska…"></textarea></label><p class="error-note" role="alert"></p><button class="app-button" type="submit">Lähetä palaute</button><small class="field-help">${window.AjouraRoles&&window.AjouraRoles.feedbackOnline()?'Palaute menee suoraan AJOURAn tekijöille.':'Palaute avautuu puhelimen jakovalikkoon, josta valitset vastaanottajan (esim. WhatsApp).'} Mukaan liitetään sovelluksen versio ja laitetyyppi, ei autojesi tietoja.</small></form>`;
