  function carEdit(c){if(!isCar(c))return kindEdit(c);const y=new Date().getFullYear();return `${back('vehicle/'+c.id,'Ajoneuvo')}<h2 class="app-heading">Muokkaa ajoneuvoa</h2><form class="app-form" id="caredit-form" novalidate><label>Rekisteritunnus<input name="plate" required maxlength="7" autocomplete="off" autocapitalize="characters" inputmode="text" value="${escape(c.plate)}"></label><label>Merkki ja malli<input name="name" required minlength="2" maxlength="60" autocomplete="off" value="${escape(c.name)}"></label><label>Lempinimi <small>· valinnainen</small><input name="nick" enterkeyhint="next" maxlength="24" autocomplete="off" value="${escape(c.nick||'')}"></label><div class="form-row"><label>Vuosimalli<select name="year" required>${yearOptions(c.year)}</select></label><label>Mittarilukema (km)<input name="km" type="number" enterkeyhint="next" required min="0" max="2000000" inputmode="numeric" value="${c.km}"></label></div><label>Käyttövoima <small>· valinnainen</small><select name="fuel"><option value="">Valitse</option>${fuels.map(f=>`<option${f===c.fuel?' selected':''}>${f}</option>`).join('')}</select></label><div class="form-row"><label>Korimalli<select name="body">${bodyOrder.map(b=>`<option value="${b}"${b===c.body?' selected':''}>${Car.names[b]}</option>`).join('')}</select></label><label>Väri<select name="color">${Car.colors.map(([n,v])=>`<option value="${v}"${v===c.color?' selected':''}>${n}</option>`).join('')}</select></label></div><p class="error-note" id="form-error" role="alert"></p><div class="form-actions"><button class="app-button" type="submit">Tallenna muutokset</button><a class="app-button secondary" href="#vehicle/${c.id}">Peruuta</a><a class="owner-link" href="#owner/${c.id}">${svg(icons.user)} Omistajanvaihdos</a><button class="app-back danger-link" type="button" data-remove="${c.id}">Poista ajoneuvo</button></div></form>`;}
  function saveCarEdit(form){const c=cars.find(c=>c.id===route().id);if(!c)return;if(!isCar(c))return saveKindEdit(form,c);const d=new FormData(form),err=document.getElementById('form-error'),plate=normalPlate(String(d.get('plate')).trim()),name=String(d.get('name')).trim().replace(/\s+/g,' '),nick=String(d.get('nick')).trim().slice(0,24),year=Number(d.get('year')),km=Number(d.get('km')),fuel=String(d.get('fuel')),body=String(d.get('body')),color=String(d.get('color')),max=new Date().getFullYear()+1;
    if(!plateOk(plate)){err.textContent='Tarkista rekisteritunnus.';return;}if(name.length<2||name.length>60){err.textContent='Kirjoita merkki ja malli.';return;}if(!Number.isInteger(year)||year<1930||year>max){err.textContent=`Vuosimallin pitää olla väliltä 1930–${max}.`;return;}if(String(d.get('km')).trim()===''){err.textContent='Syötä nykyinen mittarilukema.';return;}if(!Number.isSafeInteger(km)||km<0||km>2000000){err.textContent='Tarkista mittarilukema.';return;}if(!Car.bodies.includes(body)||!Car.colors.some(([,v])=>v===color)||(fuel!==''&&!fuels.includes(fuel))){err.textContent='Tarkista valinnat.';return;}if(km<maxKm(c)){err.textContent=`Mittarilukema ei voi olla pienempi kuin historiaan kirjattu ${number(maxKm(c))} km. Korjaa tarvittaessa ensin väärä merkintä.`;return;}
    if(c.gen&&(c.body!==body||c.year!==year||c.name!==name))delete c.gen;Object.assign(c,{plate,name,nick,year,km,fuel,body,color});persist();notice='✓ Tiedot päivitetty.';go('vehicle/'+c.id);}
  // Right after a vehicle is saved: the two things a new user usually wants next, so adding three cars is a quick loop.
  const addedNext=c=>`<div class="added-next"><h3>Mitä seuraavaksi?</h3><a class="app-button" href="#add/${c.id}">＋ Kirjaa viimeisin huolto</a><a class="app-button secondary" href="#newcar">＋ Lisää seuraava ajoneuvo</a><p>${isCar(c)?'Vanhoja huoltoja ei tarvitse kirjata heti. Viimeisin huolto ja katsastus riittävät muistutuksiin.':'Vanhoja huoltoja ei tarvitse kirjata heti. Viimeisin huolto riittää muistutukseen.'}</p></div>`;
  function vehicle(c){const sorted=[...c.events].sort(newest),year=today().slice(0,4);return `${back('vehicles','Ajoneuvot')}<div class="vehicle-hero">${vehicleImage(c)}<h2 class="app-heading">${escape(carName(c))}</h2><p>${c.nick?escape(c.name)+' · ':''}${[c.plate?escape(c.plate):'',c.year,typeOf(c),colorName(c.color),c.fuel?escape(c.fuel):'',c.engine?escape(c.engine):''].filter(Boolean).join(' · ')}</p><div class="photo-actions"><label class="photo-button">＋ ${c.photo?'Lisää kuvia':'Lisää omia kuvia'}<input type="file" accept="image/*" multiple data-car-photos="${c.id}" class="sr-only"></label>${c.photo?`<button type="button" class="photo-button plain" data-photo-remove="${c.id}">Poista pääkuva</button>`:''}<a class="photo-button" href="#caredit/${c.id}">Muokkaa tietoja</a></div>${carGallery(c)}</div>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}${notice&&/lisätty talliin\.$/.test(notice)?addedNext(c):''}<div class="app-stats"><div><strong>${number(c.km)} <small>${ku(c)}</small></strong><span>${hourly(c)?'Käyttötunnit':'Mittarilukema'}</span></div><div><strong>${c.events.length}</strong><span>Merkintää</span></div></div><div class="cost-line"><span>Kirjatut kulut yhteensä</span><strong>${number(costOf(c.events))} €</strong><small>Vuonna ${year}: ${number(costOf(c.events.filter(e=>e.date.startsWith(year))))} €</small>${(f=>f?`<small class="fuel-cost">${unitOf(c)==='kWh'?'Latauskulut':'Polttoaine'} ${year}: ${number(f)} €</small>`:'')((c.fuels||[]).filter(f=>f.date.startsWith(year)&&f.cost!==null).reduce((m,f)=>m+f.cost,0))}</div>${notesCard(c)}${fuelCard(c)}<a class="app-button" href="#add/${c.id}">＋ Lisää merkintä</a>${upcoming(c)}${tipsCard(c)}${kmChart(c)}<div class="history-heading"><h3>Huoltohistoria</h3><a href="#report/${c.id}">Raportti →</a></div>${sorted.length?timeline(c,sorted):'<p class="app-empty">Ei vielä tapahtumia. Lisää ensimmäinen merkintä yllä olevasta painikkeesta.</p>'}<p class="app-note">${c.sample?'Esimerkkiauto: kuvitteellinen historia, rekisteritunnus ja hinnat. ':''}${c.photo?'Kuva on omasi ja pysyy tässä laitteessa.':(isCar(c)?'Automalli on tyylitelty kuvitus valitsemastasi korimallista ja väristä. Voit vaihtaa tilalle oman kuvan.':'Kuva on piirretty kuvitus valitsemastasi tyypistä ja väristä. Voit vaihtaa tilalle oman kuvan.')}</p><button class="app-back danger-link" type="button" data-remove="${c.id}">Poista ajoneuvo</button>`;}
  // Own photos of the car: the first is the cover shown in the garage, the rest form a gallery under it.
  function carGallery(c){const g=c.gallery||[];if(!g.length)return '';return `<div class="car-gallery" aria-label="Kuvat autosta">${g.map((src,i)=>`<span class="att-thumb"><button type="button" class="att-open" data-view-src="${i}" data-view-kind="gallery" data-view-target="car:${c.id}" aria-label="Avaa kuva ${i+1}"><img src="${src}" alt=""></button><button type="button" class="att-remove" data-att-remove="gallery" data-att-index="${i}" data-att-target="car:${c.id}" aria-label="Poista kuva ${i+1}">×</button><button type="button" class="cover-pick" data-cover="${c.id}" data-cover-index="${i}" aria-label="Aseta kuva ${i+1} pääkuvaksi" title="Pääkuvaksi">★</button></span>`).join('')}</div><p class="gallery-help">${g.length+1} kuvaa · ★ vaihtaa pääkuvan</p>`;}
  async function addCarPhotos(input){const c=cars.find(c=>c.id===input.dataset.carPhotos);if(!c)return;const files=[...(input.files||[])];input.value='';if(!files.length)return;
    const before={photo:c.photo,gallery:[...(c.gallery||[])]},room=12-before.gallery.length+(c.photo?0:1),use=files.slice(0,Math.max(0,room));let bad=0,added=0;
    for(const f of use){const d=await shrink(f,900,.8);if(!d){bad++;continue;}if(!c.photo)c.photo=d;else(c.gallery||(c.gallery=[])).push(d);added++;}
    if(added&&!savedOk()){c.photo=before.photo;if(!c.photo)delete c.photo;c.gallery=before.gallery;persist();notice='Kuvia ei voitu tallentaa: laitteen tila ei riitä.';}
    else notice=added?`✓ ${added===1?'Kuva':added+' kuvaa'} tallennettu.`+(files.length>use.length?' Autolle mahtuu enintään 13 kuvaa.':''):bad?'Kuvia ei voitu avata. Valitse kuvatiedostoja.':'Autolle mahtuu enintään 13 kuvaa.';
    if(c.gallery&&!c.gallery.length)delete c.gallery;const y=screen.scrollTop;render();screen.scrollTop=y;}
  function setCover(btn){const c=cars.find(c=>c.id===btn.dataset.cover),i=Number(btn.dataset.coverIndex);if(!c||!c.gallery||!c.gallery[i])return;const next=c.gallery[i];if(c.photo)c.gallery[i]=c.photo;else c.gallery.splice(i,1);c.photo=next;persist();notice='✓ Pääkuva vaihdettu.';const y=screen.scrollTop;render();screen.scrollTop=y;}
  // Photos and receipts on an event. Images are shrunk on the device and kept only in this device's storage.
  let pending={photos:[],receipts:[]},pendingFor='';const attInfo={photos:['Kuvat','＋ Lisää kuvia','Esim. vaihdetut osat tai työn jälki.',900,.75],receipts:['Kuitit','＋ Lisää kuitti','Ota kuva kuitista tai valitse se kuvista.',1400,.8]};
  const attThumbs=(kind,target,list)=>list.map((src,i)=>`<span class="att-thumb${kind==='receipts'?' receipt':''}"><button type="button" class="att-open" data-view-src="${i}" data-view-kind="${kind}" data-view-target="${target}" aria-label="Avaa ${kind==='receipts'?'kuitti':'kuva'} ${i+1}"><img src="${src}" alt=""></button><button type="button" class="att-remove" data-att-remove="${kind}" data-att-index="${i}" data-att-target="${target}" aria-label="Poista ${kind==='receipts'?'kuitti':'kuva'} ${i+1}">×</button></span>`).join('');
  function attSection(kind,target,list){const [title,button,help]=attInfo[kind];return `<fieldset class="att-set" id="att-${kind}"><legend>${title} <small>· ${list.length?list.length+' kpl':'valinnainen'}</small></legend><div class="att-grid">${attThumbs(kind,target,list)}<label class="att-add">${button}<input type="file" accept="image/*" multiple class="sr-only" data-att="${kind}" data-att-target="${target}"></label></div><p class="field-help">${help}</p></fieldset>`;}
  function attList(target,kind){if(target==='pending')return pending[kind];if(target.startsWith('car:')){const c=cars.find(c=>c.id===target.slice(4));return c?(c.gallery||(c.gallery=[])):null;}const [cid,eid]=target.split(':'),e=cars.find(c=>c.id===cid)?.events.find(e=>e.id===eid);if(!e)return null;return e[kind]||(e[kind]=[]);}
  function refreshAtt(target,kind,msg){if(target==='pending'){const el=document.getElementById('att-'+kind);if(el)el.outerHTML=attSection(kind,target,pending[kind]);const err=document.getElementById('form-error');if(err&&msg)err.textContent=msg;}else{if(msg)notice=msg;const y=screen.scrollTop;render();screen.scrollTop=y;}}
  function shrink(file,max,q){return new Promise(res=>{if(!/^image\//.test(file.type))return res(null);const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const k=Math.min(1,max/Math.max(img.width,img.height)),cv=document.createElement('canvas');cv.width=Math.round(img.width*k);cv.height=Math.round(img.height*k);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(url);res(cv.toDataURL('image/jpeg',q));};img.onerror=()=>{URL.revokeObjectURL(url);res(null);};img.src=url;});}
  function savedOk(){return persist();}
  async function addAtt(input){const kind=input.dataset.att,target=input.dataset.attTarget,list=attList(target,kind);if(!list)return;const [, , , max,q]=attInfo[kind],files=[...input.files].slice(0,12-list.length);let added=0,bad=0;for(const f of files){const d=await shrink(f,max,q);if(d){list.push(d);added++;}else bad++;}
    let msg=bad?'Osaa tiedostoista ei voitu avata. Valitse kuvatiedostoja.':'';if(input.files.length>files.length)msg=kind==='gallery'?'Enintään 12 lisäkuvaa autoa kohden.':'Enintään 12 kpl per tapahtuma.';
    if(target!=='pending'&&added){if(savedOk())msg=msg||'✓ Tallennettu.';else{list.splice(list.length-added,added);msg='Ei tallennettu: laitteen tila ei riitä.';}}
    refreshAtt(target,kind,msg);}
  function removeAtt(btn){const kind=btn.dataset.attRemove,target=btn.dataset.attTarget,list=attList(target,kind);if(!list)return;list.splice(Number(btn.dataset.attIndex),1);if(target!=='pending')persist();refreshAtt(target,kind,target==='pending'?'':'Poistettu.');}
  function viewAtt(btn){const list=attList(btn.dataset.viewTarget,btn.dataset.viewKind);const src=list&&list[Number(btn.dataset.viewSrc)];if(!src)return;const d=document.createElement('dialog');d.className='att-viewer';d.innerHTML=`<img src="${src}" alt="${btn.dataset.viewKind==='receipts'?'Kuitti':'Kuva'}"><button type="button" class="app-button secondary">Sulje</button>`;document.body.appendChild(d);d.addEventListener('close',()=>d.remove());d.addEventListener('click',ev=>{if(ev.target===d||ev.target.closest('button'))d.close();});d.showModal();}
  const partRow=(x={name:'',qty:'',price:''})=>`<div class="part-row"><input name="partName" maxlength="60" placeholder="Osa, merkki tai tuotenumero" value="${escape(x.name)}" aria-label="Osa"><input name="partQty" maxlength="12" placeholder="esim. 4 l" value="${escape(x.qty)}" aria-label="Määrä"><input name="partPrice" type="number" min="0" step="0.01" inputmode="decimal" placeholder="€" value="${escape(x.price)}" aria-label="Hinta euroina"></div>`;
  function partsSection(v){const parts=v.parts||[],has=parts.length||v.labor||v.other;return `<details class="check-set parts-set"${has?' open':''}><summary>Kulut eriteltyinä <small>· varaosat, työ, muut</small></summary><div class="part-head"><span>Varaosa</span><span>Määrä</span><span>€</span></div><div class="part-rows">${(parts.length?parts:[{name:'',qty:'',price:''},{name:'',qty:'',price:''}]).map(partRow).join('')}</div><button class="app-back" type="button" data-add-part>＋ Lisää rivi</button><div class="form-row"><label>Työ (€)<input name="labor" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0" value="${escape(v.labor||'')}"></label><label>Muut (€)<input name="other" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0" value="${escape(v.other||'')}"></label></div><p class="field-help" id="parts-total">Yhteensä lasketaan kustannukseen automaattisesti.</p></details>`;}
  function readParts(data){const n=data.getAll('partName'),q=data.getAll('partQty'),p=data.getAll('partPrice');return n.map((name,i)=>({name:String(name).trim().slice(0,60),qty:String(q[i]).trim().slice(0,12),price:String(p[i]).trim()})).filter(x=>x.name||x.price).slice(0,30);}
  function syncPartsTotal(form){const data=new FormData(form),parts=readParts(data),labor=String(data.get('labor')||''),other=String(data.get('other')||'');if(!parts.length&&!labor&&!other){const cost=form.elements.cost;if(cost.dataset.auto!==undefined&&Number(cost.dataset.auto)===Number(cost.value)){cost.value='';delete cost.dataset.auto;}return;}const sum=[...parts.map(x=>x.price),labor,other].reduce((a,v)=>a+(Number(v)||0),0);const cost=form.elements.cost,auto=Math.round(sum*100)/100;if(cost.value===''||(cost.dataset.auto!==undefined&&Number(cost.dataset.auto)===Number(cost.value))){if(auto>0){cost.value=auto;cost.dataset.auto=String(auto);document.getElementById('parts-total').textContent='Yhteensä '+number(sum)+' € (päivitetty kustannukseen).';}else{cost.value='';delete cost.dataset.auto;document.getElementById('parts-total').textContent='Lisää hinnat, niin summa päivittyy kustannukseen.';}}else document.getElementById('parts-total').textContent='Eriteltyjen summa '+number(sum)+' €. Kustannukseen kirjoittamasi summa säilyy.';}
  function add(c,e){const v=e||{type:'',date:today(),km:'',cost:'',note:'',items:[]},items=v.items||[];if(e&&!pendingFor){pendingFor=e.id;pending={photos:[...(e.photos||[])],receipts:[...(e.receipts||[])]};}
    return `${back(e?'event/'+c.id+'/'+e.id:'vehicle/'+c.id,e?'Merkintä':'Ajoneuvo')}<h2 class="app-heading">${e?'Muokkaa merkintää':'Uusi merkintä'}</h2><p class="app-subtitle">${escape(carName(c))} · ${plateTxt(c)}<br>${e?'Tarkenna tietoja, lisää kuitit ja kuvat.':'Pakollisia ovat vain tyyppi ja päivämäärä. Loput voit lisätä myöhemmin.'}</p><form class="app-form" id="event-form"><label>Tapahtuma<select name="type" required><option value="">Valitse tapahtuman tyyppi</option>${[...kindsFor(c),...(v.type&&!kindsFor(c).includes(v.type)?[v.type]:[])].map(k=>`<option${k===v.type?' selected':''}>${k}</option>`).join('')}</select></label><label>Päivämäärä<input name="date" type="date" value="${v.date}" max="${today()}" min="${c.year-1}-01-01" required></label><label>${meterLabel(c)} <small>· valinnainen</small><input name="km" type="number" min="0" max="2000000" step="1" inputmode="numeric" placeholder="${c.km}" value="${v.km===null?'':v.km}"></label><p class="field-help">Viimeisin kirjattu lukema: ${number(c.km)} ${ku(c)}.</p><label>Kustannus (€) <small>· valinnainen</small><input name="cost" type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="0,00" value="${escape(v.cost||'')}"${(()=>{const sum=Math.round([...(v.parts||[]).map(x=>x.price),v.labor,v.other].reduce((a,x)=>a+(Number(x)||0),0)*100)/100;return v.cost!==''&&v.cost!==undefined&&String(sum)===String(Number(v.cost))?` data-auto="${sum}"`:'';})()}></label>${partsSection(v)}<details class="check-set"${items.length?' open':''}><summary>Tehdyt toimenpiteet <small>· ${items.length?items.length+' valittu':'valinnainen'}</small></summary><div class="check-grid">${checkItems.map(i=>`<label class="check-item"><input type="checkbox" name="items" value="${i}"${items.includes(i)?' checked':''}><span>${i}</span></label>`).join('')}</div></details><label>Muistiinpano <small>· valinnainen</small><textarea name="note" maxlength="300" rows="3" placeholder="Esim. öljy ja suodatin vaihdettu itse">${escape(v.note||'')}</textarea></label>${attSection("photos","pending",pending.photos)}${attSection("receipts","pending",pending.receipts)}<p class="error-note" id="form-error" role="alert"></p><div class="form-actions"><button class="app-button" type="submit">${e?'Tallenna muutokset':'Tallenna'}</button><a class="app-button secondary" href="#${e?'event/'+c.id+'/'+e.id:'vehicle/'+c.id}">Peruuta</a>${e?`<button class="app-back danger-link" type="button" data-delete-event="${e.id}">Poista merkintä</button>`:''}</div><p class="app-fineprint">${keepNote}</p></form>`;}
  function detail(c,e){return `${back('vehicle/'+c.id,'Huoltohistoria')}<div class="detail-icon" aria-hidden="true">${eventIcon(e.type)}</div><h2 class="app-heading">${escape(e.type)}</h2><p class="app-subtitle">${escape(carName(c))} · ${plateTxt(c)}</p><dl class="detail-list"><div><dt>PÄIVÄMÄÄRÄ</dt><dd>${date(e.date)}</dd></div><div><dt>${hourly(c)?'TUNTIMITTARI':'MITTARILUKEMA'}</dt><dd>${e.km===null?'Ei merkitty':number(e.km)+' '+ku(c)}</dd></div><div><dt>KUSTANNUS</dt><dd>${e.cost!==''?number(e.cost)+' €':'Ei merkitty'}</dd></div><div><dt>MUISTIINPANO</dt><dd>${e.note?`<span translate="no">${escape(e.note)}</span>`:'Ei muistiinpanoa.'}</dd></div>${e.parts?.length||e.labor||e.other?`<div><dt>KULUT ERITELTYINÄ</dt><dd><ul class="done-list">${(e.parts||[]).map(x=>`<li><span translate="no">${escape(x.name)}</span>${x.qty?' · '+escape(x.qty):''}${x.price?' · '+number(x.price)+' €':''}</li>`).join('')}${e.labor?`<li>Työ · ${number(e.labor)} €</li>`:''}${e.other?`<li>Muut · ${number(e.other)} €</li>`:''}</ul></dd></div>`:''}${e.items?.length?`<div><dt>TEHDYT TOIMENPITEET</dt><dd><ul class="done-list">${e.items.map(i=>`<li>${i}</li>`).join('')}</ul></dd></div>`:''}</dl><a class="app-button" href="#edit/${c.id}/${e.id}">Muokkaa merkintää</a><div class="app-form detail-att">${attSection('photos',c.id+':'+e.id,e.photos||[])}${attSection('receipts',c.id+':'+e.id,e.receipts||[])}</div>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}<a class="app-button secondary" href="#vehicle/${c.id}">Takaisin ajoneuvoon</a>${c.sample&&!e.id.startsWith('new')?'<p class="app-fineprint">Kuvitteellinen esimerkkimerkintä.</p>':''}`;}
  function me(){return `${top()}<p class="app-greeting">${greet()}</p><h2 class="app-heading">Omat asetukset</h2>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}<form class="app-form" id="me-form" novalidate><label>Nimesi <small>· valinnainen</small><input name="name" maxlength="24" autocomplete="given-name" placeholder="Etunimi" value="${escape(profile.name)}"></label><fieldset class="interval-set"><legend>Huoltomuistutuksen väli</legend><div class="form-row"><label>Kuukautta<input name="months" type="number" required min="1" max="36" step="1" inputmode="numeric" value="${profile.months}"></label><label>Kilometriä<input name="km" type="number" enterkeyhint="next" required min="1000" max="60000" step="500" inputmode="numeric" value="${profile.km}"></label></div><p class="field-help">Tarkista oikea väli autosi huolto-ohjelmasta. Muistutus tulee sen mukaan, kumpi täyttyy ensin.</p></fieldset><p class="error-note" id="form-error" role="alert"></p><button class="app-button" type="submit">Tallenna asetukset</button></form><div class="me-data"><h3>Tili <small class="soon-tag">tulossa</small></h3><p>Myöhemmin kirjautumalla autosi ja merkintäsi tallentuvat turvallisesti ja siirtyvät mukanasi uuteen puhelimeen. Siihen asti käytä varmuuskopiota.</p><button class="app-button secondary" type="button" data-login>Kirjaudu sisään <small class="soon-tag">tulossa</small></button>${loginNote?'<p class="login-note" role="status"><strong>Kirjautuminen on tulossa.</strong> Sitä ennen tiedot pysyvät tässä laitteessa.</p>':''}</div><div class="me-data"><h3>Varmuuskopio</h3><p>Tallenna autot, merkinnät ja tankkaukset tiedostoon. Palauttamalla tiedoston saat ne takaisin, myös uudessa puhelimessa. Palautus yhdistää tiedot: sama auto päivittyy ja uudet lisätään.</p><div class="backup-actions"><button class="app-button" type="button" data-backup>Tallenna varmuuskopio</button><label class="app-button secondary">Palauta varmuuskopio<input type="file" accept="application/json,.json" class="sr-only" data-restore></label></div><p class="app-fineprint">${stamp(backupKey)?'Viimeisin varmuuskopio: '+date(new Date(stamp(backupKey)).toISOString().slice(0,10)):'Varmuuskopiota ei ole vielä otettu tällä laitteella.'}</p></div><div class="me-data"><h3>Anna palautetta</h3><p>Testaatko AJOURAa? Kerro, mikä toimi ja mikä ei.</p>${feedbackForm()}</div><div class="me-data"><h3>Suosittele AJOURAa</h3><p>Jaa linkki kaverille. Sovellus asennetaan suoraan selaimesta.</p><button class="app-button secondary" type="button" data-share-app>Jaa linkki</button></div><div class="me-data"><h3>Kieli ja ulkoasu</h3>${prefsBar()}</div><div class="me-data"><h3>Tietosi</h3><p>Autot, merkinnät ja nimesi tallentuvat vain tähän laitteeseen. Mitään ei lähetetä palvelimelle.${installed?'':' Asenna AJOURA puhelimen kotivalikkoon: selain voi muuten poistaa tiedot, jos sivulla ei käydä pitkään aikaan. Ota myös varmuuskopio.'}</p><button class="app-button secondary danger" type="button" data-reset>Poista kaikki tiedot</button></div><p class="app-fineprint">AJOURA ${appVersion} · <a href="tietosuoja.html">Tietosuoja</a></p>`;}
  // Each screen remembers its scroll position, so going back (or re-rendering after a choice) does not jump to the top.
